def _jcs_canonicalize(value: Any) -> bytes:
    """Serialize a JSON value per RFC 8785 (JCS) and return UTF-8 bytes."""
    if value is None:
        return b"null"
    if value is True:
        return b"true"
    if value is False:
        return b"false"
    if isinstance(value, str):
        return _jcs_string(value).encode("utf-8")
    if _is_int(value):
        return str(value).encode("ascii")
    if isinstance(value, list):
