_JCS_ESCAPES = {
    '"': '\\"', "\\": "\\\\", "\b": "\\b", "\t": "\\t",
    "\n": "\\n", "\f": "\\f", "\r": "\\r",
}

def _jcs_string(text):
    parts = ['"']
    for char in text:
        escape = _JCS_ESCAPES.get(char)
        if escape is not None:
            parts.append(escape)
        elif ord(char) < 0x20:
            parts.append(f"\\u{ord(char):04x}")
        else:
            parts.append(char)
    parts.append('"')
    return "".join(parts)
